import {makeDemo,localDate} from './demo.js';

const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',map:'M4 3h6v6H4zM14 15h6v6h-6zM3 15h6v6H3zM7 9v3h10v3M7 12v3',calendar:'M5 5h14a2 2 0 0 1 2 2v13H3V7a2 2 0 0 1 2-2ZM7 3v4m10-4v4M3 11h18M7 15h2m3 0h2m3 0h1',check:'m5 12 4 4L19 6',tasks:'M9 5h12M9 12h12M9 19h12M3 5h1m-1 7h1m-1 7h1',chart:'M4 3v17h17M8 15v-4m5 4V7m5 8V4',money:'M3 5h18v14H3zM3 9a4 4 0 0 0 4-4m10 0a4 4 0 0 0 4 4M3 15a4 4 0 0 1 4 4m10 0a4 4 0 0 1 4-4M14 12a2 2 0 1 1-4 0 2 2 0 0 1 4 0',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-3.87M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0m3-3.87a4 4 0 0 1 0 7.75',partners:'m3 12 5-6 4 1 4-1 5 6-6 7-3-1-3 1Zm5-6 4 4-3 3 2 2 5-5m-9 6 2 2m6-3 2 2',idea:'M9 18h6m-5 3h4M8 14a6 6 0 1 1 8 0l-1 2H9Z',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M10 2h4l1 3 3 1 3-1 2 4-2 3 1 3-2 4-3-1-3 1-1 3h-4l-1-3-3-1-3 1-2-4 2-3-1-3 2-4 3 1 3-1Z',plus:'M12 5v14M5 12h14',arrow:'M5 12h14m-5-5 5 5-5 5',left:'m14 6-6 6 6 6',right:'m10 6 6 6-6 6',close:'m6 6 12 12M6 18 18 6',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4',logout:'M9 4H4v16h5m5-4 4-4-4-4M8 12h13',link:'m10 14 4-4m-7 5-2 2a4 4 0 0 0 6 5l3-3m-1-10 2-2a4 4 0 0 1 6 5l-3 3',search:'M20 20l-5-5M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',menu:'M4 6h16M4 12h16M4 18h16',download:'M12 3v12m-4-4 4 4 4-4M4 16v5h16v-5',spark:'m12 2 2 7 7 3-7 3-2 7-2-7-7-3 7-3Z',globe:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M3 12h18M12 3c5 5 5 13 0 18-5-5-5-13 0-18',lab:'M9 3h6m-5 0v7l-6 9a1 1 0 0 0 1 2h14a1 1 0 0 0 1-2l-6-9V3M7 15h10',heart:'M20 5c-3-3-7-1-8 2-1-3-5-5-8-2-5 5 2 11 8 15 6-4 13-10 8-15',book:'M12 5v16M3 3c4 0 7 0 9 2 2-2 5-2 9-2v15c-4 0-7 0-9 3-2-3-5-3-9-3Z',shield:'m12 3 8 3v6c0 5-5 8-8 10-3-2-8-5-8-10V6ZM8 12l3 3 5-6'};
const icon=(name,cls='')=>`<svg class="${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[name]||icons.grid}"/></svg>`;
const statusNames={idea:'Идея',planned:'Запланировано',doing:'В работе',ready:'Готово',scheduled:'В очереди',published:'Опубликовано',done:'Завершено',queued:'В очереди',processing:'Отправляется',failed:'Ошибка',uncertain:'Проверить отправку',cancelled:'Отменено'};
const roleNames={marketer:'Маркетолог',leadership:'Руководство',staff:'Сотрудник',doctor:'Врач',it:'IT-отдел'};
const routes={dashboard:['Обзор','home'],directions:['Направления','grid'],map:['Карта развития','map'],calendar:['Контент-план','calendar'],approvals:['Согласования','check'],tasks:['Задачи команды','tasks'],analytics:['Статистика','chart'],'weekly-reports':['Отчёты за неделю','calendar'],finance:['Финансы','money'],doctors:['Врачи','users'],partners:['Партнёры','partners'],events:['События','calendar'],ideas:['Идеи команды','idea'],settings:['Настройки','settings']};
let cfg={},data=null,current='dashboard',direction='',branch='',query='',calendarMode='month',calendarDate=new Date(localDate()+'T12:00:00Z'),mapZoom=1;
let dateTo=localDate();let dateFrom=new Date(Date.now()-41*86400000).toISOString().slice(0,10);let saving=false;
const money=n=>new Intl.NumberFormat('ru-RU',{maximumFractionDigits:0}).format(n)+' с.';
const number=n=>new Intl.NumberFormat('ru-RU').format(n);
const fmtDate=(s,opts={day:'numeric',month:'short'})=>s?new Date(s.length===10?s+'T12:00:00Z':s).toLocaleDateString('ru-RU',{timeZone:'Asia/Tashkent',...opts}):'Без даты';
const dayOf=s=>s?localDate(new Date(s)):'';
const manager=()=>['marketer','leadership'].includes(data?.profile?.role);
const leader=()=>data?.profile?.role==='leadership';
const memberName=id=>data.profiles.find(p=>p.id===id)?.display_name||'Не назначен';
const dir=id=>data.directions.find(d=>d.id===id);
const dtag=id=>{const d=dir(id);return d?`<span class="tag" style="color:${esc(d.color)}"><i class="dot" style="--color:${esc(d.color)}"></i>${esc(d.short_name)}</span>`:'<span class="tag neutral">Общее</span>';};
const badge=s=>`<span class="tag ${['ready','published','done'].includes(s)?'ready':['doing','processing'].includes(s)?'purple':['failed','uncertain'].includes(s)?'error':'neutral'}">${esc(statusNames[s]||s)}</span>`;
const button=(label,action,secondary=false,ic='plus')=>`<button class="button ${secondary?'secondary':''}" data-action="${action}">${icon(ic)}${label}</button>`;
const empty=(title,text='Добавьте первую запись, чтобы начать работу.')=>`<div class="empty"><strong>${title}</strong>${text}</div>`;
const uuid=()=>crypto.randomUUID();
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');setTimeout(()=>$('#toast').classList.remove('visible'),4200);}
function persist(){if(cfg.demo)localStorage.setItem('fd-demo-v1',JSON.stringify(data));}
async function api(path,options={},retry=true){const r=await fetch(path,{...options,headers:{'Content-Type':'application/json',...options.headers}});if(r.status===401&&retry&&!path.startsWith('/api/auth/')){const refreshed=await fetch('/api/auth/refresh',{method:'POST'});if(refreshed.ok)return api(path,options,false);}const value=await r.json();if(!r.ok)throw Object.assign(new Error(value.error||'Не удалось выполнить действие.'),{status:r.status});return value;}
async function load(){if(cfg.demo){try{const saved=JSON.parse(localStorage.getItem('fd-demo-v1'));data=saved?.schema===1?{...makeDemo(),...saved}:makeDemo();if(data.palette!=='violet-blue'){const base=makeDemo();data.directions.forEach(d=>{const match=base.directions.find(x=>x.id===d.id);if(match)d.color=match.color;});data.palette='violet-blue';persist();}}catch{data=makeDemo();}}else data=await api(`/api/bootstrap?from=${dateFrom}&to=${dateTo}`);}
async function reload(){await load();render();}
function go(route){history.pushState({},'',`/${route}`);current=route;render();window.scrollTo(0,0);}
function filtered(rows,dateField){return rows.filter(r=>(!direction||r.direction_id===direction)&&(!branch||!r.branch_id||r.branch_id===branch)&&(!dateField||r[dateField]&&r[dateField].slice(0,10)>=dateFrom&&r[dateField].slice(0,10)<=dateTo));}
function financial(){const reports=filtered(data.weekly_reports,'week_start'),ids=new Set(reports.map(r=>r.id));const receipts=(data.weekly_receipts||[]).filter(r=>ids.has(r.report_id));const expenses=branch?[]:filtered(data.expenses||[],'paid_on').filter(e=>e.type!=='budget');return{reports,receipts,expenses,inquiries:sum(reports,'inquiries'),bookings:sum(reports,'bookings'),visits:sum(reports,'first_visits'),revenue:sum(receipts,'amount'),spend:sum(expenses,'amount')};}
const sum=(rows,key)=>rows.reduce((s,r)=>s+(Number(r[key])||0),0);
function approvalsFor(plan){const votes=data.plan_approvals.filter(v=>v.plan_id===plan.id);const yes=new Set(votes.filter(v=>v.decision==='approved'&&data.profiles.some(p=>p.id===v.reviewer_id&&p.role==='leadership'&&p.active)).map(v=>v.reviewer_id));return{votes,count:yes.size,approved:yes.size>=2};}
function filters(withDates=true){return `<div class="filters"><label for="direction-filter">Показать</label><select id="direction-filter"><option value="">Все направления</option>${data.directions.filter(d=>!d.archived).map(d=>`<option value="${d.id}" ${direction===d.id?'selected':''}>${esc(d.short_name)}</option>`).join('')}</select><select id="branch-filter" aria-label="Филиал"><option value="">Оба филиала</option>${data.branches.filter(b=>!b.archived).map(b=>`<option value="${b.id}" ${branch===b.id?'selected':''}>${esc(b.name)}</option>`).join('')}</select>${withDates?`<span class="filter-sep"></span><label for="date-from">С</label><input id="date-from" type="date" value="${dateFrom}" aria-label="Начало периода"><label for="date-to">по</label><input id="date-to" type="date" value="${dateTo}" aria-label="Конец периода">`:''}<span class="filter-sep"></span><span class="tag neutral">TJS · сомони</span></div>`;}
function heading(eyebrow,title,description,actions=''){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${description}</p></div><div class="head-actions">${actions}</div></div>`;}
function metric(label,value,note,ic='chart',dark=false){return `<div class="metric ${dark?'dark':''}"><div class="metric-top">${label}${icon(ic)}</div><div class="metric-value">${value}</div><div class="metric-note">${note}</div></div>`;}
function table(headers,rows){return rows.length?`<div class="table-wrap"><table><thead><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:empty('Записей пока нет','Измените фильтры или добавьте данные.');}
function link(value,label){try{const u=new URL(value);return ['https:','http:'].includes(u.protocol)?`<a class="detail-link" href="${esc(u.href)}" target="_blank" rel="noopener noreferrer">${esc(label||value)} ↗</a>`:'';}catch{return '';}}
function nav(){return Object.entries(routes).filter(([k])=>k!=='finance'||manager()).map(([key,[label,ic]],i)=>`${key==='analytics'?'<div class="nav-label">РЕЗУЛЬТАТЫ</div>':key==='doctors'?'<div class="nav-label">КОМАНДА И РЕСУРСЫ</div>':''}<a href="/${key}" data-nav="${key}" class="${current===key?'active':''}" ${current===key?'aria-current="page"':''}>${icon(ic)}${label}${key==='approvals'&&data.content_plans.some(p=>!approvalsFor(p).approved)?`<span class="nav-count">${data.content_plans.filter(p=>!approvalsFor(p).approved).length}</span>`:''}</a>`).join('');}
function render(){
 if(!data)return login();
 if(!routes[current])current='dashboard';if(current==='finance'&&!manager())current='dashboard';
 const pages={dashboard,directions:directionsPage,map:mapPage,calendar:calendarPage,approvals:approvalsPage,tasks:tasksPage,analytics:analyticsPage,'weekly-reports':weeklyPage,finance:financePage,doctors:doctorsPage,partners:partnersPage,events:eventsPage,ideas:ideasPage,settings:settingsPage};
 document.title=`${routes[current][0]} · Family Dent`;
 $('#app').innerHTML=`<div class="shell"><button class="mobile-scrim" data-action="menu" aria-label="Закрыть меню"></button><aside class="sidebar"><a href="/dashboard" data-nav="dashboard" class="brand"><img src="/assets/family-dent.png" alt="Family Dent"><small>Marketing space</small></a><div class="nav-label">РАБОЧЕЕ ПРОСТРАНСТВО</div><nav class="nav" aria-label="Главное меню">${nav()}</nav><div class="side-bottom"><div class="side-note"><strong>Шесть направлений. Одна команда.</strong>Планируем, создаём и видим результат вместе.</div><div class="user"><span class="avatar">${esc(data.profile.display_name.split(' ').map(s=>s[0]).slice(0,2).join(''))}</span><div><strong>${esc(data.profile.display_name)}</strong><small>${roleNames[data.profile.role]}</small></div><button class="icon-button" data-action="logout" aria-label="Выйти">${icon('logout')}</button></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumbs"><button class="icon-button mobile-menu" data-action="menu" aria-label="Открыть меню">${icon('menu')}</button><span>Рабочее пространство</span>${icon('right')}<span>${routes[current][0]}</span></div><div class="top-actions"><span class="muted" style="font-size:11px">${fmtDate(localDate(),{day:'numeric',month:'long',year:'numeric'})}</span><span class="tag ready">${cfg.demo?'Демо':'Family Dent'}</span><button class="icon-button" data-action="alerts" aria-label="Уведомления">${icon('bell')}</button></div></header><div class="content">${cfg.demo?`<div class="demo-banner"><span>Демонстрационный режим · все цифры вымышлены, изменения сохраняются только в этом браузере.</span><select id="demo-role" aria-label="Посмотреть от лица сотрудника">${data.profiles.map(p=>`<option value="${p.id}" ${data.profile.id===p.id?'selected':''}>${esc(p.display_name)}</option>`).join('')}</select></div>`:''}${pages[current]()}<div class="footer-note"><span>Family Dent · пространство маркетинга</span><span>Ташкент / Душанбе · UTC+5 · только сводные данные</span></div></div></main></div>`;
}
function dashboard(){
 const f=financial();const items=filtered(data.content_items);const published=items.filter(c=>c.status==='published').length;
 return heading('ОБЗОР МАРКЕТИНГА','Всё важное — перед вами','Шесть направлений Family Dent в одном рабочем пространстве.',manager()?button('Добавить материал','new:content_items'):button('Мои задачи','my-tasks',true,'tasks'))+filters()+`<div class="metrics">${manager()?metric('Оплаты первичных пациентов',money(f.revenue),'Полученные оплаты · без вычета расходов','money',true):metric('Первичные посещения',number(f.visits),'По внесённым отчётам','users',true)}${metric('Обращения',number(f.inquiries),`${number(f.bookings)} записей за выбранный период`,'users')}${manager()?metric('Расходы на маркетинг',branch?'—':money(f.spend),branch?'Расходы учитываются по направлениям':'Фактические расходы · без планового бюджета','chart'):metric('Задачи в работе',data.tasks.filter(t=>t.status!=='done').length,'Открытые задачи команды','tasks')}${metric('Опубликовано материалов',published,`${items.length} материалов в контент-плане`,'calendar')}</div><div class="two-col"><section class="panel"><div class="panel-head"><div><h2>Как меняются результаты</h2><p>Обращения и первичные посещения по неделям</p></div><div class="chart-legend"><span><i class="dot"></i>Обращения</span><span><i class="dot" style="--color:#c8b5e9"></i>Посещения</span></div></div>${lineChart(f.reports)}<p class="chart-caption">График строится по внесённым отчётам. Пропуски не означают нулевой результат.</p></section><section class="panel"><div class="panel-head"><h2>В фокусе команды</h2><a href="/tasks" data-nav="tasks" class="text-link">Все задачи ${icon('arrow')}</a></div>${taskRows(filtered(data.tasks).filter(t=>t.status!=='done').slice(0,4))}</section></div><div class="section-head"><h2>Наши направления</h2><a class="text-link" href="/map" data-nav="map">Открыть карту развития ${icon('arrow')}</a></div><div class="direction-grid">${data.directions.filter(d=>!d.archived&&(!direction||d.id===direction)).map(directionCard).join('')}</div><section class="panel"><div class="panel-head"><h2>Ближайшие публикации</h2><a href="/calendar" data-nav="calendar" class="text-link">Весь контент-план ${icon('arrow')}</a></div>${contentTable(items.filter(c=>c.status!=='published').sort((a,b)=>(a.publish_at||'z').localeCompare(b.publish_at||'z')).slice(0,4))}</section>`;
}
function directionCard(d){const cs=data.content_items.filter(c=>c.direction_id===d.id);const done=cs.filter(c=>c.status==='published').length;const tasks=data.tasks.filter(t=>t.direction_id===d.id&&t.status!=='done').length;const i=data.directions.indexOf(d);return `<button class="direction-card" style="--color:${esc(d.color)}" data-direction="${d.id}"><div class="direction-top"><span class="direction-symbol">${icon(['heart','book','globe','lab','shield','spark'][i%6])}</span><span class="tag ${i===5?'warn':'neutral'}">${i===5?'Подготовка запуска':`${tasks} задач`}</span></div><h3>${esc(d.name)}</h3><p>${esc(d.description)}</p><div class="direction-bottom"><span>Опубликовано материалов</span><span>${done} / ${cs.length}</span></div><div class="progress"><span style="width:${cs.length?done/cs.length*100:0}%"></span></div></button>`;}
function lineChart(reports){
 const grouped=new Map();for(const r of reports){const prev=grouped.get(r.week_start)||{inquiries:0,first_visits:0};prev.inquiries+=r.inquiries||0;prev.first_visits+=r.first_visits||0;grouped.set(r.week_start,prev);}
 const values=[...grouped].sort((a,b)=>a[0].localeCompare(b[0]));if(!values.length)return empty('График появится после первого отчёта','Сомон или маркетолог может внести данные за неделю.');
 const max=Math.max(10,...values.map(([,v])=>v.inquiries),...values.map(([,v])=>v.first_visits));const x=i=>45+i*(555/Math.max(values.length-1,1)),y=v=>175-v/max*150;
 const pathFor=k=>values.map(([,v],i)=>`${i?'L':'M'}${x(i)},${y(v[k])}`).join(' ');
 return `<svg class="chart" viewBox="0 0 640 215" role="img" aria-label="Динамика обращений и первичных посещений"><title>Еженедельные обращения и первичные посещения</title>${[0,1,2,3].map(n=>`<path class="chart-grid" d="M40 ${25+n*50}H620"/><text x="0" y="${29+n*50}">${number(Math.round(max*(1-n/3)))}</text>`).join('')}<path class="chart-area" d="${pathFor('inquiries')}L${x(values.length-1)},175L45,175Z"/><path class="chart-line" d="${pathFor('inquiries')}"/><path class="chart-line secondary" d="${pathFor('first_visits')}"/>${values.map(([date,v],i)=>`<circle cx="${x(i)}" cy="${y(v.inquiries)}" r="3" fill="#79a3d8"><title>${fmtDate(date)}: ${v.inquiries} обращений, ${v.first_visits} посещений</title></circle>${values.length<10||i%Math.ceil(values.length/8)===0?`<text x="${x(i)}" y="205" text-anchor="middle">${fmtDate(date)}</text>`:''}`).join('')}</svg>`;
}
function taskRows(tasks){return tasks.length?`<div class="task-list">${tasks.map(t=>`<div class="task-row"><button class="task-check ${t.status==='done'?'done':''}" data-task-toggle="${t.id}" aria-label="${t.status==='done'?'Вернуть в работу':'Завершить'}: ${esc(t.title)}" ${manager()||t.assignee_id===data.profile.id?'':'disabled'}>${t.status==='done'?icon('check'):''}</button><div class="task-text ${t.status==='done'?'done':''}"><strong>${esc(t.title)}</strong><small>${esc(dir(t.direction_id)?.short_name||'Общее')} · ${esc(memberName(t.assignee_id))}</small></div><span class="task-date">${fmtDate(t.due_date)}</span></div>`).join('')}</div>`:empty('Здесь спокойно','Нет открытых задач по выбранным фильтрам.');}
function contentTable(items){return table(['Материал','Направление','Дата','Исполнитель','Этап'],items.map(c=>[`<button class="text-link row-title" data-content="${c.id}">${esc(c.title)}</button><span class="subtitle">${esc(c.format)} · ${esc(c.language)}</span>`,dtag(c.direction_id),fmtDate(c.publish_at),esc(memberName(c.assignee_id)),badge(c.status)]));}
function directionsPage(){return heading('СТРАТЕГИЯ','Шесть направлений','Цели, каналы продвижения и работа команды.',manager()?button('Добавить направление','new:directions'):'')+`<div class="direction-grid">${data.directions.filter(d=>!d.archived).map(directionCard).join('')}</div><div class="section-head"><h2>${direction?esc(dir(direction)?.name):'Цели направлений'}</h2>${manager()?button('Добавить цель','new:goals',true):''}</div>${table(['Цель','Направление','Канал','Результат','Срок','Этап'],filtered(data.goals).map(g=>[`<button class="text-link" data-edit="goals:${g.id}">${esc(g.title)}</button>`,dtag(g.direction_id),esc(g.channel),esc(g.target),fmtDate(g.due_date),badge(g.status)]))}`;}
function mapPage(){return heading('ОБЩАЯ КАРТИНА','Карта развития','От целей каждого направления — к конкретным действиям.',manager()?button('Добавить цель','new:goals'):'')+`<div class="map-controls"><button class="button secondary small" data-action="zoom-out">−</button><span class="muted" style="font-size:11px">${Math.round(mapZoom*100)}%</span><button class="button secondary small" data-action="zoom-in">+</button><button class="button secondary small" data-action="zoom-reset">Сбросить</button></div><div class="map-viewport"><div class="map-tree" style="zoom:${mapZoom}"><div class="map-root">Family Dent · развитие маркетинга</div>${data.directions.filter(d=>!d.archived).map(d=>`<div class="map-branch"><button class="map-node" style="--color:${esc(d.color)}" data-direction="${d.id}">${esc(d.name)}</button><div class="map-leaves">${data.goals.filter(g=>g.direction_id===d.id).map(g=>`<div class="map-leaf"><strong>${esc(g.title)}</strong><small>${esc(g.channel)} · ${esc(g.target)}</small>${badge(g.status)}<small>${data.tasks.filter(t=>t.goal_id===g.id).map(t=>`${esc(t.title)} · ${esc(statusNames[t.status])}`).join('<br>')||'Свяжите задачи с этой целью'}</small></div>`).join('')||`<div class="map-leaf">Цели ещё не добавлены<small>Начните с ближайшей задачи развития</small></div>`}</div></div>`).join('')}</div></div>`;}
function calendarPage(){
 const year=calendarDate.getUTCFullYear(),month=calendarDate.getUTCMonth();const first=calendarMode==='week'?new Date(calendarDate):new Date(Date.UTC(year,month,1));const start=new Date(first);start.setUTCDate(start.getUTCDate()-((start.getUTCDay()+6)%7));const cells=[];
 const items=filtered(data.content_items).filter(c=>!query||c.title.toLowerCase().includes(query.toLowerCase()));
 for(let i=0;i<(calendarMode==='week'?7:42);i++){const d=new Date(start);d.setUTCDate(d.getUTCDate()+i);const date=d.toISOString().slice(0,10);cells.push(`<div class="day ${d.getUTCMonth()!==month?'other':''} ${date===localDate()?'today':''}"><span class="day-number">${d.getUTCDate()}</span>${items.filter(c=>dayOf(c.publish_at)===date).map(c=>`<button class="calendar-item" style="--color:${esc(dir(c.direction_id)?.color||'#9b80cc')}" data-content="${c.id}">${esc(c.title)}<small>${esc(c.format)} · ${esc(statusNames[c.status])}</small></button>`).join('')}</div>`);}
 return heading('ПЛАНИРУЕМ И СОЗДАЁМ','Контент-план','Один календарь для всех аккаунтов и направлений.',manager()?button('Добавить материал','new:content_items')+button('Новый план','new:content_plans',true,'calendar'):'')+filters(false)+`<div class="direction-legend">${data.directions.filter(d=>!d.archived).map(d=>`<span><i class="dot" style="--color:${esc(d.color)}"></i>${esc(d.short_name)}</span>`).join('')}</div><div class="calendar-toolbar"><div class="horizontal"><button class="icon-button" data-action="prev-month" aria-label="Предыдущий месяц">${icon('left')}</button><h2>${esc(calendarDate.toLocaleDateString('ru-RU',{month:'long',year:'numeric',timeZone:'UTC'}))}</h2><button class="icon-button" data-action="next-month" aria-label="Следующий месяц">${icon('right')}</button></div><div class="segmented">${[['month','Месяц'],['week','Неделя'],['list','Список']].map(([k,n])=>`<button class="${calendarMode===k?'active':''}" data-calendar-mode="${k}">${n}</button>`).join('')}</div></div>${calendarMode!=='list'?`<div class="calendar-scroll"><div class="calendar">${['ПН','ВТ','СР','ЧТ','ПТ','СБ','ВС'].map(d=>`<div class="day-name">${d}</div>`).join('')}${cells.join('')}</div></div>`:contentTable(items.sort((a,b)=>(a.publish_at||'z').localeCompare(b.publish_at||'z')))}`;
}
function approvalsPage(){return heading('КОМАНДНОЕ РЕШЕНИЕ','Согласования','План одобряют два разных представителя руководства. Проверки врачей — отдельно.',manager()?button('Создать план','new:content_plans'):'')+`<div class="approval-grid">${data.content_plans.map(p=>{const a=approvalsFor(p);return `<section class="panel"><div class="panel-head"><h2>${esc(p.title)}</h2><span class="tag ${a.approved?'ready':'warn'}">${a.approved?'Одобрен':`${a.count} из 2`}</span></div><p class="muted" style="font-size:11px">${fmtDate(p.starts_on)} — ${fmtDate(p.ends_on)}</p><div class="review-votes">${a.votes.map(v=>`<div class="vote ${v.decision==='approved'?'yes':'no'}">${esc(memberName(v.reviewer_id))}<br>${v.decision==='approved'?'Одобрено':'Отклонено'}${v.comment?`<br>${esc(v.comment)}`:''}</div>`).join('')||'<span class="muted" style="font-size:12px">Решений пока нет</span>'}</div><div class="approval-status">${data.content_items.filter(c=>c.plan_id===p.id).length} материалов · изменения после одобрения сохраняются в истории.</div><div class="mini-actions"><button class="button secondary small" data-plan-view="${p.id}">Посмотреть план</button>${leader()?`<button class="button small" data-approve="${p.id}:approved">Одобрить</button><button class="button danger small" data-approve="${p.id}:rejected">Отклонить</button>`:''}</div></section>`;}).join('')||empty('Планы ещё не созданы','Маркетолог может создать первый контент-план.')}</div><div class="section-head spaced"><h2>Материалы для проверки врачами</h2></div>${contentTable(filtered(data.content_items).filter(c=>c.status!=='published'))}`;}
function tasksPage(){const tasks=filtered(data.tasks).filter(t=>!query||t.title.toLowerCase().includes(query.toLowerCase()));return heading('РАБОТА КОМАНДЫ','Задачи','Съёмки, дизайн, сайт и развитие направлений.',button('Добавить задачу','new:tasks'))+filters(false)+`<div class="board">${[['planned','Запланировано'],['doing','В работе'],['done','Завершено']].map(([status,title])=>`<section class="board-column"><h3>${title}<span>${tasks.filter(t=>t.status===status).length}</span></h3>${tasks.filter(t=>t.status===status).map(t=>`<div class="board-item">${dtag(t.direction_id)}<h4>${esc(t.title)}</h4><p>${esc(memberName(t.assignee_id))}<br>${fmtDate(t.due_date)}</p>${t.link?link(t.link,'Материалы'):''}<div class="mini-actions spaced">${manager()||t.assignee_id===data.profile.id?`<button class="button secondary small" data-edit="tasks:${t.id}">Изменить</button><button class="button subtle small" data-task-toggle="${t.id}">${status==='done'?'Вернуть':'Завершить'}</button>`:''}</div></div>`).join('')||'<p class="muted" style="font-size:11px">Пока нет задач</p>'}</section>`).join('')}</div>`;}
function analyticsPage(){const f=financial();const snapshots=data.social_metric_snapshots.filter(r=>!direction||data.social_accounts.some(a=>a.id===r.account_id&&a.direction_id===direction));const followers=data.social_accounts.filter(a=>!direction||a.direction_id===direction).reduce((n,a)=>n+(snapshots.find(s=>s.account_id===a.id&&s.metric==='followers_count')?.value||0),0);return heading('ИЗМЕРЯЕМ РЕЗУЛЬТАТ','Статистика продвижения','Результаты площадок и сводные показатели направлений.',button('Выгрузить CSV','export',true,'download'))+filters()+`<div class="metrics">${metric('Обращения',number(f.inquiries),'За выбранный период','users',true)}${metric('Записи',number(f.bookings),'По еженедельным отчётам','calendar')}${metric('Первичные посещения',number(f.visits),f.bookings?`${Math.round(f.visits/f.bookings*100)}% от количества записей`:'Нет данных для расчёта','check')}${metric('Подписчики',snapshots.length?number(followers):'—','Последнее доступное значение подключённых аккаунтов','users')}</div><section class="panel"><div class="panel-head"><h2>Обращения и посещения по неделям</h2></div>${lineChart(f.reports)}</section><div class="section-head spaced"><h2>Результаты по направлениям</h2></div>${table(['Направление','Обращения','Записи','Первичные посещения','Отчётов'],data.directions.filter(d=>!direction||d.id===direction).map(d=>{const rows=f.reports.filter(r=>r.direction_id===d.id);return[dtag(d.id),rows.length?number(sum(rows,'inquiries')):'—',rows.length?number(sum(rows,'bookings')):'—',rows.length?number(sum(rows,'first_visits')):'—',rows.length];}))}<div class="section-head spaced"><h2>Данные социальных сетей</h2></div>${snapshots.length?table(['Аккаунт','Показатель','Значение','Период','Обновлено'],snapshots.slice(0,25).map(s=>[esc(data.social_accounts.find(a=>a.id===s.account_id)?.handle),esc(s.metric),number(s.value),esc(s.period),fmtDate(s.observed_at)])):empty('Аккаунты ещё не передают статистику','Подключите Meta в настройках. Вымышленные охваты не подставляются.')}<p class="chart-caption">Показатели соцсетей — последние полученные снимки; фильтр периода выше относится к еженедельным отчётам.</p>`;}
function weeklyPage(){const f=financial();return heading('ЕЖЕНЕДЕЛЬНЫЙ УЧЁТ','Отчёты за неделю','Отдельно по филиалу, направлению и источнику обращения.',manager()?button('Внести данные','weekly-form'):'')+filters()+`<div class="info-strip">Только сводные числа. Не вводите имена, телефоны, диагнозы и сведения об отдельных пациентах. Повторное сохранение той же недели, филиала, направления и источника обновляет запись.</div>${table(['Неделя с','Филиал','Направление','Источник','Обращения','Записи','Первичные посещения',...(manager()?['Оплаты']:[])],f.reports.sort((a,b)=>b.week_start.localeCompare(a.week_start)).map(r=>[fmtDate(r.week_start),esc(data.branches.find(b=>b.id===r.branch_id)?.name),dtag(r.direction_id),esc(data.categories.find(c=>c.id===r.source_id)?.name),r.inquiries??'—',r.bookings??'—',r.first_visits??'—',...(manager()?[data.weekly_receipts.some(x=>x.report_id===r.id)?money(data.weekly_receipts.find(x=>x.report_id===r.id).amount):'Не внесены']:[])]))}`;}
function financePage(){if(!manager())return empty('Доступ ограничен');const f=financial();return heading('ФИНАНСОВЫЙ ОБЗОР','Расходы и поступления','Полученные оплаты первичных пациентов и затраты на продвижение.',button('Добавить расход','new:expenses')+button('Кампания','new:campaigns',true)+button('Выгрузить CSV','export',true,'download'))+filters()+`<div class="metrics">${metric('Оплаты первичных пациентов',money(f.revenue),'Выручка · без вычета расходов на лечение','money',true)}${metric('Расходы',branch?'—':money(f.spend),branch?'Нет распределения расходов по филиалам':'Факт · без планового бюджета','chart')}${metric('Стоимость обращения',!branch&&f.inquiries&&f.spend?money(f.spend/f.inquiries):'—','Сопоставление за период, без доказанной связи','users')}${metric('Бюджет',branch?'—':money(sum(filtered(data.expenses,'paid_on').filter(e=>e.type==='budget'),'amount')),'Плановые суммы учитываются отдельно','calendar')}</div><div class="info-strip">Оплаты и расходы одной недели могут относиться к разным кампаниям и разным пациентским потокам. Это сравнение за период, а не прибыль и не доказанная окупаемость рекламы. Общие расходы не распределяются автоматически. При выборе филиала расходы скрыты, поскольку их распределение по филиалам пока не ведётся.</div>${table(['Назначение','Направление','Категория','Дата','Тип','Сумма'],(branch?[]:filtered(data.expenses,'paid_on')).sort((a,b)=>b.paid_on.localeCompare(a.paid_on)).map(e=>[`<button class="text-link" data-edit="expenses:${e.id}">${esc(e.title)}</button>`,dtag(e.direction_id),esc(data.categories.find(c=>c.id===e.category_id)?.name||'Не указана'),fmtDate(e.paid_on),esc({regular:'Регулярный',one_off:'Разовый',budget:'Плановый бюджет'}[e.type]),money(e.amount)]))}`;}
function doctorsPage(){return heading('ЛИЦА FAMILY DENT','Продвижение врачей','Следим за участием врачей с учётом специальности и доступности.',manager()?button('Добавить врача','new:doctors'):'')+`<div class="info-strip">Счётчики ниже относятся к текущему календарному месяцу. Цель задаётся индивидуально; одинаковое число публикаций для всех не обязательно.</div><div class="doctor-grid">${data.doctors.filter(d=>!d.archived).map(d=>{const cs=data.content_items.filter(c=>data.content_doctors.some(x=>x.content_id===c.id&&x.doctor_id===d.id)&&dayOf(c.publish_at).startsWith(localDate().slice(0,7)));const done=cs.filter(c=>c.status==='published');return `<section class="panel"><div class="doctor-top"><span class="avatar">${esc(d.name.split(' ').slice(0,2).map(n=>n[0]).join(''))}</span><div><h3>${esc(d.name)}</h3><p>${esc(d.specialty)}</p></div></div><p class="muted" style="font-size:11px">${esc(data.branches.find(b=>b.id===d.branch_id)?.name||'Несколько филиалов')}</p><div class="doctor-numbers"><span>Опубликовано <strong>${done.length}</strong></span><span>План <strong>${d.monthly_target}</strong></span></div><div class="progress" style="--color:#a783d1"><span style="width:${d.monthly_target?Math.min(100,done.length/d.monthly_target*100):0}%"></span></div><p class="sync-line">В контент-плане: ${cs.length} · ${done.length?'Последняя: '+fmtDate(done.sort((a,b)=>(b.publish_at||'').localeCompare(a.publish_at||''))[0].publish_at):'Публикаций в этом месяце пока нет'}</p>${manager()?`<button class="button secondary small" data-edit="doctors:${d.id}">Изменить</button>`:''}</section>`;}).join('')||empty('Добавьте врачей','Пациентские данные для этого раздела не нужны.')}</div>`;}
function partnersPage(){return heading('РАЗВИВАЕМ СОТРУДНИЧЕСТВО','Партнёры','Организации, договорённости и следующие действия.',button('Добавить партнёра','new:partners'))+filters(false)+table(['Организация','Направление','Ответственный','Этап','Следующее действие','Дата'],filtered(data.partners).map(p=>[`<button class="text-link" data-partner="${p.id}">${esc(p.name)}</button><span class="subtitle">${esc(p.kind)}</span>`,dtag(p.direction_id),esc(memberName(p.owner_id)),`<span class="tag neutral">${esc(p.status)}</span>`,esc(p.next_action),fmtDate(p.next_date)]));}
function eventsPage(){return heading('ВАЖНЫЕ ДАТЫ','События и мероприятия','Съёмки, курсы, праздники и подготовка открытия.',button('Добавить событие','new:events'))+filters(false)+`<div class="event-list">${filtered(data.events).sort((a,b)=>a.starts_on.localeCompare(b.starts_on)).map(e=>`<section class="panel event-card"><div class="date-tile"><strong>${new Date(e.starts_on+'T12:00:00Z').getUTCDate()}</strong>${fmtDate(e.starts_on,{month:'short'})}</div><div style="flex:1"><h3>${esc(e.title)}</h3><p>${esc(e.kind)} · ${esc(dir(e.direction_id)?.short_name||'Все направления')}</p><p>${esc(e.description)}</p></div>${manager()||e.created_by===data.profile.id?`<button class="icon-button" data-edit="events:${e.id}" aria-label="Изменить событие">${icon('right')}</button>`:''}</section>`).join('')||empty('Календарь пока свободен','Добавьте даты подготовки и открытия нового отделения.')}</div>`;}
function ideasPage(){return heading('СОЗДАЁМ ВМЕСТЕ','Идеи команды','Сохраняем предложения, чтобы вернуться к ним вовремя.',button('Предложить идею','new:ideas'))+filters(false)+`<div class="approval-grid">${filtered(data.ideas).map(i=>`<section class="panel">${dtag(i.direction_id)}<h3 style="font-size:16px;font-weight:500">${esc(i.title)}</h3><p class="idea-description">${esc(i.description)}</p><p class="sync-line">${esc(memberName(i.created_by))}</p><div class="mini-actions"><button class="button secondary small" data-idea-task="${i.id}">Создать задачу</button>${manager()||i.created_by===data.profile.id?`<button class="button secondary small" data-edit="ideas:${i.id}">Изменить</button>`:''}</div></section>`).join('')||empty('Место для новых идей','Предложение может добавить любой участник команды.')}</div>`;}
function settingsPage(){return heading('РАБОЧЕЕ ПРОСТРАНСТВО','Настройки и подключения','Аккаунты, справочники и доступ команды.')+`<div class="settings-grid"><section class="panel"><div class="panel-head"><h2>Социальные сети</h2>${['marketer','leadership','it'].includes(data.profile.role)?button('Подключить Meta','connect-meta',true,'link'):''}</div>${data.social_accounts.filter(a=>!a.archived).map(a=>`<div class="account-row"><span class="direction-symbol" style="--color:${esc(dir(a.direction_id)?.color||'#a28bb9')}">${icon(a.platform==='instagram'?'grid':'globe')}</span><div class="account-name">${link(a.url,a.handle)}<small>${a.platform==='instagram'?'Instagram':'Facebook'} · ${esc(dir(a.direction_id)?.short_name||'Направление уточняется')}</small><small>${a.last_synced_at?'Обновлено '+fmtDate(a.last_synced_at):'Синхронизация ещё не выполнялась'}</small></div><span class="tag ${a.connection_status==='connected'?'ready':'warn'}">${a.connection_status==='connected'?'Подключён':a.connection_status==='needs_attention'?'Требует внимания':'Не подключён'}</span>${['marketer','leadership','it'].includes(data.profile.role)?`<button class="icon-button" data-edit="social_accounts:${a.id}" aria-label="Изменить аккаунт">${icon('settings')}</button>`:''}</div>`).join('')}<p class="notes spaced">Аккаунт нового отделения ещё не создан. Его можно добавить после запуска. Автопубликация: ${cfg.publishing?'включена':'выключена до проверки подключения'}.</p><div class="panel-head spaced"><h2>Материалы команды</h2></div>${link('https://drive.google.com/drive/folders/1Wi7QqNeVQiD7m3o0-TsS0MYZctnUcnTZ','Папка Google Drive')}<p class="sync-line">Для публикации нужен доступ к самому файлу. Закрытые ссылки и страницы просмотра требуют отдельной проверки.</p></section><section class="panel notes"><div class="panel-head"><h2>Права и приватность</h2></div><p><strong>Финансы</strong><br>Маркетолог, руководство и Сомон.</p><p><strong>Одобрение планов</strong><br>Два разных представителя руководства. Сомон участвует на тех же условиях.</p><p><strong>Проверка врачами</strong><br>Отдельная отметка медицинской проверки.</p><p><strong>Пациентские данные</strong><br>В приложении только сводные количества и суммы. Таблицы пациентов не загружаются.</p><p><strong>Доступ сотрудников</strong><br>Учётные записи и роли выдаёт IT-руководитель через Supabase.</p>${cfg.demo?button('Сбросить демо','reset-demo',true,'settings'):''}</section></div><div class="section-head spaced"><h2>Справочники</h2><div class="mini-actions">${['marketer','leadership','it'].includes(data.profile.role)?button('Добавить аккаунт','new:social_accounts',true):''}${manager()?button('Добавить категорию','new:categories',true):''}</div></div>${table(['Тип','Категория','Состояние',''],data.categories.map(c=>[esc({source:'Источник обращения',expense:'Расход',service:'Услуга',format:'Формат контента',partner:'Партнёр'}[c.kind]),esc(c.name),c.archived?'В архиве':'Активна',manager()?`<button class="text-link" data-edit="categories:${c.id}">Изменить</button>`:'']))}<div class="section-head spaced"><h2>Команда</h2></div>${table(['Сотрудник','Роль','Статус'],data.profiles.map(p=>[esc(p.display_name),roleNames[p.role],p.active?'Доступ открыт':'Ожидает активации']))}${manager()?`<div class="section-head spaced"><h2>Последние изменения</h2></div>${table(['Дата','Раздел','Действие','Сотрудник'],(data.audit_log||[]).slice(0,15).map(a=>[fmtDate(a.created_at),esc(a.table_name),esc(a.action),esc(memberName(a.actor_id))]))}`:''}`;}

function modal(title,html){const el=$('#modal');el.innerHTML=`<div class="modal-head"><h2 id="modal-title">${esc(title)}</h2><button class="icon-button" data-action="close-modal" aria-label="Закрыть окно">${icon('close')}</button></div><div class="modal-body">${html}</div>`;if(!el.open)el.showModal();}
const field=(name,label,type='text',value='',extra='')=>`<label class="form-field ${type==='textarea'?'full':''}">${label}${type==='textarea'?`<textarea name="${name}" ${extra}>${esc(value)}</textarea>`:`<input name="${name}" type="${type}" value="${esc(value)}" ${extra}>`}</label>`;
function select(name,label,options,value='',required=false){return `<label class="form-field">${label}<select name="${name}" ${required?'required':''}><option value="">${required?'Выберите':'Не указано'}</option>${options.map(o=>{const [v,n]=Array.isArray(o)?o:[o.id,o.name||o.title||o.display_name];return `<option value="${esc(v)}" ${value===v?'selected':''}>${esc(n)}</option>`;}).join('')}</select></label>`;}
const formEnd=label=>`<div class="form-error" role="alert"></div><div class="form-footer"><button type="button" class="button secondary" data-action="close-modal">Отмена</button><button class="button" type="submit">${label||'Сохранить'}</button></div>`;
function entityForm(table,id=null,prefill={}){
 const r=id?data[table].find(x=>x.id===id):{...prefill};if(!r)return;
 const dirs=data.directions.filter(d=>!d.archived),members=data.profiles.filter(p=>p.active),cats=kind=>data.categories.filter(c=>c.kind===kind&&!c.archived);
 const ds=(required=true)=>select('direction_id','Направление',dirs,r.direction_id||direction,required);
 const title=()=>field('title','Название','text',r.title||'','required maxlength="300"');
 const status=(opts=['planned','doing','done'])=>select('status','Этап',opts.map(s=>[s,statusNames[s]]),r.status||opts[0],true);
 const person=(name='assignee_id',label='Исполнитель')=>select(name,label,manager()?members:members.filter(p=>p.id===data.profile.id),r[name]||(!manager()?data.profile.id:''));
 let html='',name='';
 if(table==='content_items'){
  if(!data.content_plans.length){toast('Сначала создайте контент-план.');return entityForm('content_plans');}
  name=id?'Изменить материал':'Новый материал';html=title()+ds()+select('plan_id','Контент-план',data.content_plans,r.plan_id||data.content_plans[0]?.id,true)+select('format','Формат',cats('format').map(c=>[c.name,c.name]),r.format||'Рилс',true)+select('language','Язык',[['RU','Русский'],['TJ','Таджикский'],['EN','Английский']],r.language||'RU',true)+field('publish_at','Дата и время · UTC+5','datetime-local',r.publish_at?new Date(new Date(r.publish_at).getTime()+5*3600000).toISOString().slice(0,16):'')+person()+status(['idea','planned','doing','ready','scheduled','published'])+field('objective','Цель','text',r.objective)+field('asset_url','Ссылка на фото или видео','url',r.asset_url)+field('body','Текст публикации','textarea',r.body)+`<label class="form-field full">Врачи в материале<select name="doctor_ids" multiple size="3">${data.doctors.filter(d=>!d.archived).map(d=>`<option value="${d.id}" ${data.content_doctors.some(x=>x.content_id===id&&x.doctor_id===d.id)?'selected':''}>${esc(d.name)}</option>`).join('')}</select><small>Можно выбрать нескольких врачей (Ctrl / Cmd).</small></label>`;
 }else if(table==='content_plans'){name='Контент-план';html=title()+field('starts_on','Начало периода','date',r.starts_on||localDate().slice(0,8)+'01','required')+field('ends_on','Конец периода','date',r.ends_on||localDate(),'required');
 }else if(table==='tasks'){name=id?'Изменить задачу':'Новая задача';html=title()+ds(false)+person()+field('due_date','Срок','date',r.due_date)+status()+select('goal_id','Цель',data.goals,r.goal_id)+select('content_id','Материал',data.content_items,r.content_id)+field('link','Ссылка на результат','url',r.link);
 }else if(table==='goals'){name='Цель направления';html=title()+ds()+field('channel','Канал продвижения','text',r.channel)+field('target','Ожидаемый результат','text',r.target)+field('due_date','Срок','date',r.due_date)+status();
 }else if(table==='expenses'){name='Расход или бюджет';html=title()+ds(false)+field('amount','Сумма · сомони','number',r.amount,'required min="0.01" max="999999999999.99" step="0.01"')+field('paid_on','Дата','date',r.paid_on||localDate(),'required')+select('category_id','Категория',cats('expense'),r.category_id)+select('type','Тип',[['regular','Регулярный расход'],['one_off','Разовый расход'],['budget','Плановый бюджет']],r.type||'regular',true)+select('campaign_id','Кампания',data.campaigns,r.campaign_id);
 }else if(table==='doctors'){name='Карточка врача';html=field('name','Имя врача','text',r.name,'required')+field('specialty','Специальность','text',r.specialty)+select('branch_id','Филиал',data.branches,r.branch_id)+field('monthly_target','Цель публикаций в месяц','number',r.monthly_target??2,'required min="0" step="1"');
 }else if(table==='partners'){name='Партнёр';html=field('name','Название организации','text',r.name,'required')+ds(false)+field('kind','Тип организации','text',r.kind||'Клиника')+person('owner_id','Ответственный')+select('status','Этап',['Найти контакт','Связаться','Отправлено предложение','Назначена встреча','Сотрудничаем','Пауза','Отказ'].map(v=>[v,v]),r.status||'Найти контакт',true)+field('next_action','Следующее действие','text',r.next_action)+field('next_date','Дата следующего действия','date',r.next_date);
 }else if(table==='events'){name='Событие';html=title()+ds(false)+field('starts_on','Дата','date',r.starts_on||localDate(),'required')+field('kind','Тип события','text',r.kind||'Мероприятие')+field('description','Описание','textarea',r.description);
 }else if(table==='ideas'){name='Идея команды';html=title()+ds(false)+field('description','Описание','textarea',r.description);
 }else if(table==='categories'){name='Категория';html=select('kind','Тип',[['source','Источник обращения'],['expense','Расход'],['service','Услуга'],['format','Формат контента'],['partner','Партнёр']],r.kind||'source',true)+field('name','Название','text',r.name,'required')+select('archived','Состояние',[['false','Активна'],['true','В архиве']],String(r.archived||false),true);
 }else if(table==='directions'){name='Направление';html=field('name','Полное название','text',r.name,'required')+field('short_name','Короткое название','text',r.short_name,'required')+field('color','Цвет','color',r.color||'#9b80cc','required')+field('description','Описание','textarea',r.description);
 }else if(table==='social_accounts'){name='Социальный аккаунт';html=select('platform','Площадка',[['instagram','Instagram'],['facebook','Facebook']],r.platform||'instagram',true)+field('handle','Имя аккаунта или ID страницы','text',r.handle,'required')+field('url','Ссылка на аккаунт','url',r.url,'required')+ds(false)+field('external_id','ID аккаунта в Meta (если известен)','text',r.external_id,'pattern="[0-9]+"')+select('archived','Состояние',[['false','Активен'],['true','В архиве']],String(r.archived||false),true);
 }else if(table==='campaigns'){name='Рекламная кампания';html=title()+ds()+select('source_id','Источник',cats('source'),r.source_id,true)+field('starts_on','Начало','date',r.starts_on||localDate(),'required')+field('ends_on','Окончание','date',r.ends_on)+status();
 }
 if(!html)return;modal(name,`<form data-entity-form="${table}" data-id="${id||''}"><div class="form-grid">${html}</div>${formEnd()}</form>`);
}
function weeklyForm(){
 const day=new Date(localDate()+'T12:00:00Z');day.setUTCDate(day.getUTCDate()-((day.getUTCDay()+6)%7));
 modal('Внести данные за неделю',`<p class="weekly-intro">Заполните отдельный отчёт для каждого филиала, направления и источника. Пустое поле означает «не внесено», ноль — подтверждённое отсутствие результата. Повторное сохранение обновит прежнюю запись.</p><form id="weekly-form"><div class="form-grid">${field('week_start','Понедельник отчётной недели','date',day.toISOString().slice(0,10),'required')}${select('branch_id','Филиал',data.branches,branch,true)}${select('direction_id','Направление',data.directions,direction,true)}${select('source_id','Источник обращения',data.categories.filter(c=>c.kind==='source'&&!c.archived),'',true)}${select('campaign_id','Кампания',data.campaigns)}${field('inquiries','Обращения','number','','min="0" step="1"')}${field('bookings','Записи','number','','min="0" step="1"')}${field('first_visits','Первичные посещения','number','','min="0" step="1"')}${field('registrations','Регистрации на обучение','number','','min="0" step="1"')}${field('participants','Участники обучения','number','','min="0" step="1"')}${field('orders','Заказы лаборатории','number','','min="0" step="1"')}${field('receipt','Оплаты первичных пациентов · сомони','number','','required min="0" max="999999999999.99" step="0.01"')}</div>${formEnd('Сохранить отчёт')}</form>`);
}
function contentDetail(id){const c=data.content_items.find(c=>c.id===id);if(!c)return;const plan=data.content_plans.find(p=>p.id===c.plan_id),a=plan&&approvalsFor(plan);const reviews=data.medical_reviews.filter(v=>v.content_id===id);modal(c.title,`<div class="detail-meta">${dtag(c.direction_id)}${badge(c.status)}<span class="tag neutral">${esc(c.format)} · ${esc(c.language)}</span></div><p class="muted" style="font-size:12px">${fmtDate(c.publish_at,{day:'numeric',month:'long',hour:'2-digit',minute:'2-digit'})} · ${esc(memberName(c.assignee_id))}</p><p class="sync-line">План: ${esc(plan?.title)} · ${a?.approved?'одобрен':'ожидает одобрения'} (${a?.count||0}/2)</p><div class="detail-body">${esc(c.body||'Текст ещё не добавлен')}</div>${c.asset_url?link(c.asset_url,'Открыть материалы'):'<span class="muted" style="font-size:12px">Материалы ещё не прикреплены</span>'}<div class="content-actions">${manager()?`<button class="button secondary small" data-edit="content_items:${id}">Изменить</button><button class="button small" data-schedule="${id}">Запланировать отправку</button><button class="button secondary small" data-manual="${id}">Указать ссылку на публикацию</button>`:''}${['doctor','leadership'].includes(data.profile.role)?`<button class="button subtle small" data-medical="${id}:approved">Проверено врачом</button><button class="button danger small" data-medical="${id}:rejected">Нужны исправления</button>`:''}</div><p class="sync-line">${reviews.map(v=>`${esc(memberName(v.reviewer_id))}: ${v.decision==='approved'?'проверено':'нужны исправления'}${v.comment?' — '+esc(v.comment):''}`).join('<br>')||'Медицинская проверка пока не отмечена.'}</p><div class="section-head spaced"><h2>Комментарии</h2></div>${data.comments.filter(x=>x.content_id===id).map(x=>`<div class="comment"><small>${esc(memberName(x.author_id))} · ${fmtDate(x.created_at)}</small>${esc(x.body)}</div>`).join('')||'<p class="muted" style="font-size:12px">Комментариев пока нет.</p>'}<form id="comment-form" data-content-id="${id}"><div class="form-grid">${field('body','Добавить комментарий','textarea','','required maxlength="5000"')}</div>${formEnd('Отправить')}</form><div class="section-head spaced"><h2>История материала</h2></div>${(data.content_versions||[]).filter(v=>v.content_id===id).slice(-5).reverse().map(v=>`<div class="comment"><small>${esc(memberName(v.actor_id))} · ${fmtDate(v.created_at)}</small>${esc(v.title)}<br>${esc(v.body)}</div>`).join('')||'<p class="sync-line">Изменения появятся здесь после редактирования.</p>'}`);}
async function save(table,values,id){
 if(!cfg.demo){const result=await api(`/api/data/${table}${id?'/'+id:''}`,{method:id?'PATCH':'POST',body:JSON.stringify(values)});await load();return result[0];}
 const managerTables=['content_items','content_plans','goals','expenses','doctors','categories','directions','campaigns'];
 if(table==='social_accounts'&&!['marketer','leadership','it'].includes(data.profile.role))throw new Error('Недостаточно прав.');
 if(managerTables.includes(table)&&!manager())throw new Error('Недостаточно прав.');
 if(table==='tasks'&&id&&!manager()&&data.tasks.find(t=>t.id===id)?.assignee_id!==data.profile.id)throw new Error('Можно менять только назначенные вам задачи.');
 const item={...values,id:id||uuid(),created_by:data.profile.id,created_at:new Date().toISOString()};
 if(id){const index=data[table].findIndex(x=>x.id===id);item.created_by=data[table][index].created_by;data[table][index]={...data[table][index],...values};}else data[table].push(item);
 if(table==='content_items'){data.content_versions??=[];data.content_versions.push({content_id:item.id,title:item.title,body:item.body,asset_url:item.asset_url,actor_id:data.profile.id,created_at:new Date().toISOString()});}
 data.audit_log.unshift({table_name:table,record_id:item.id,actor_id:data.profile.id,action:id?'UPDATE':'INSERT',created_at:new Date().toISOString()});persist();return item;
}
async function decision(id,value,medical=false,comment=''){
 if(cfg.demo){if(medical?!['doctor','leadership'].includes(data.profile.role):!leader())throw new Error('Недостаточно прав.');const table=medical?'medical_reviews':'plan_approvals',key=medical?'content_id':'plan_id';data[table]=data[table].filter(v=>!(v[key]===id&&v.reviewer_id===data.profile.id));data[table].push({[key]:id,reviewer_id:data.profile.id,decision:value,comment,created_at:new Date().toISOString()});persist();}else{await api('/api/approval',{method:'POST',body:JSON.stringify({[medical?'content_id':'plan_id']:id,decision:value,comment,medical})});await load();}
 render();toast(value==='approved'?'Одобрение сохранено':'Замечание сохранено');
}
function decisionForm(id,value,medical=false){modal(value==='approved'?'Подтвердить одобрение':'Отправить замечание',`<form id="decision-form" data-record="${id}" data-value="${value}" data-medical="${medical}"><p class="notes">${medical?'Это отдельная отметка проверки материала профильным специалистом.':'Ваш голос будет учтён как одно одобрение контент-плана.'}</p><div class="form-grid">${field('comment','Комментарий','textarea','','maxlength="5000" '+(value==='rejected'?'required':''))}</div>${formEnd(value==='approved'?'Одобрить':'Сохранить замечание')}</form>`);}
function publicationForm(id,manual=false){const c=data.content_items.find(c=>c.id===id);modal(manual?'Добавить опубликованный материал':'Запланировать отправку',`<form id="publication-form" data-content-id="${id}" data-manual="${manual}">${manual?field('permalink','Ссылка на публикацию','url','','required'):`<p class="notes">Отправка доступна после подключения аккаунта и двух одобрений плана. Материал должен быть готов. В первой версии автоматическая отправка поддерживает одиночные фото и Instagram Reels; другие форматы можно отметить вручную.</p><div class="form-grid">${select('account_id','Аккаунт',data.social_accounts.filter(a=>!a.direction_id||a.direction_id===c.direction_id).map(a=>[a.id,`${a.platform} · ${a.handle}`]),'',true)}${field('scheduled_at','Дата и время · UTC+5','datetime-local',new Date(Date.now()+5*3600000+600000).toISOString().slice(0,16),'required')}</div>`}${formEnd(manual?'Сохранить ссылку':'Поставить в очередь')}</form>`);}

document.addEventListener('click',async e=>{
 const target=e.target.closest('button,a');if(!target)return;
 try{
 if(target.dataset.nav){e.preventDefault();return go(target.dataset.nav);}
 if(target.dataset.direction){direction=target.dataset.direction;return go('directions');}
 if(target.dataset.content)return contentDetail(target.dataset.content);
 if(target.dataset.edit){const[t,id]=target.dataset.edit.split(':');return entityForm(t,id);}
 if(target.dataset.taskToggle){const t=data.tasks.find(t=>t.id===target.dataset.taskToggle);await save('tasks',{status:t.status==='done'?'doing':'done'},t.id);render();return;}
 if(target.dataset.calendarMode){calendarMode=target.dataset.calendarMode;return render();}
 if(target.dataset.approve){const[id,value]=target.dataset.approve.split(':');return decisionForm(id,value);}
 if(target.dataset.medical){const[id,value]=target.dataset.medical.split(':');return decisionForm(id,value,true);}
 if(target.dataset.planView){const p=data.content_plans.find(p=>p.id===target.dataset.planView);return modal(p.title,contentTable(data.content_items.filter(c=>c.plan_id===p.id)));}
 if(target.dataset.schedule)return publicationForm(target.dataset.schedule);
 if(target.dataset.manual)return publicationForm(target.dataset.manual,true);
 if(target.dataset.ideaTask){const i=data.ideas.find(x=>x.id===target.dataset.ideaTask);return entityForm('tasks',null,{title:i.title,direction_id:i.direction_id});}
 if(target.dataset.partner){const p=data.partners.find(x=>x.id===target.dataset.partner);return modal(p.name,`<p class="notes">${esc(p.next_action)} · ${fmtDate(p.next_date)}</p><div class="mini-actions">${manager()||p.created_by===data.profile.id?`<button class="button secondary small" data-edit="partners:${p.id}">Изменить</button>`:''}</div><div class="section-head spaced"><h2>История работы</h2></div>${data.partner_activities.filter(x=>x.partner_id===p.id).map(x=>`<div class="comment">${esc(x.body)}<small>${esc(memberName(x.created_by))} · ${fmtDate(x.created_at)}</small></div>`).join('')}<form id="partner-activity-form" data-partner-id="${p.id}">${field('body','Записать результат встречи или звонка','textarea','','required')}${formEnd('Добавить')}</form>`);}
 const action=target.dataset.action;if(!action)return;
 if(action.startsWith('new:'))return entityForm(action.slice(4));
 if(action==='menu')return $('.shell').classList.toggle('menu-open');
 if(action==='close-modal')return $('#modal').close();
 if(action==='weekly-form')return weeklyForm();
 if(action==='recover')return modal('Восстановить доступ',`<form id="recover-form">${field('email','Рабочая почта','email','','required autocomplete="email"')}${formEnd('Отправить ссылку')}</form>`);
 if(action==='my-tasks'){query='';return go('tasks');}
 if(action==='prev-month'||action==='next-month'){calendarDate=calendarMode==='week'?new Date(Date.UTC(calendarDate.getUTCFullYear(),calendarDate.getUTCMonth(),calendarDate.getUTCDate()+(action==='next-month'?7:-7))):new Date(Date.UTC(calendarDate.getUTCFullYear(),calendarDate.getUTCMonth()+(action==='next-month'?1:-1),1));return render();}
 if(action==='zoom-in'||action==='zoom-out'||action==='zoom-reset'){mapZoom=action==='zoom-reset'?1:Math.max(.5,Math.min(1.5,mapZoom+(action==='zoom-in'?.1:-.1)));return render();}
 if(action==='reset-demo'){localStorage.removeItem('fd-demo-v1');data=makeDemo();persist();render();return toast('Демонстрационные данные восстановлены');}
 if(action==='connect-meta'){if(cfg.demo)return toast('Подключение Meta появится после настройки сервера и Supabase.');window.location.href='/api/meta/connect';return;}
 if(action==='logout'){if(cfg.demo){data.profile=data.profiles[0];persist();return toast('В демо можно сменить роль в верхней полосе.');}await api('/api/auth/logout',{method:'POST'});data=null;return login();}
 if(action==='alerts'){const tasks=data.tasks.filter(t=>t.status!=='done'&&t.due_date&&t.due_date<localDate());const sync=data.sync_runs.filter(s=>s.status!=='success').slice(0,3);return modal('Требует внимания',`<p class="notes">Просроченных задач: ${tasks.length}. Планов без двух одобрений: ${data.content_plans.filter(p=>!approvalsFor(p).approved).length}.</p>${taskRows(tasks)}${sync.map(s=>`<p class="notes">${esc(s.message)}</p>`).join('')}${data.publications.filter(p=>['failed','uncertain'].includes(p.status)).map(p=>`<p class="notes">Публикация: ${esc(p.error||statusNames[p.status])}</p>`).join('')}`);}
 if(action==='export')return exportCsv();
 }catch(err){console.error(err.stack);toast('Не удалось открыть раздел или выполнить действие. Повторите попытку.');}
});
document.addEventListener('change',async e=>{
 try{
 if(e.target.id==='direction-filter'){direction=e.target.value;render();}
 if(e.target.id==='branch-filter'){branch=e.target.value;render();}
 if(['date-from','date-to'].includes(e.target.id)){const value=e.target.value;if(!value)return;if(e.target.id==='date-from')dateFrom=value;else dateTo=value;if(dateFrom>dateTo){toast('Начало периода не может быть позже окончания.');return;}if(!cfg.demo)await load();render();}
 if(e.target.id==='demo-role'){data.profile=data.profiles.find(p=>p.id===e.target.value);persist();render();}
 }catch(err){toast(err.message);}
});
document.addEventListener('submit',async e=>{
 e.preventDefault();const form=e.target;if(saving)return;if(!form.reportValidity())return;saving=true;const submit=form.querySelector('[type=submit]');if(submit)submit.disabled=true;
 const input=Object.fromEntries(new FormData(form));const error=form.querySelector('.form-error');if(error)error.textContent='';
 try{
 if(form.id==='login-form'){await api('/api/auth/login',{method:'POST',body:JSON.stringify(input)});await load();render();return;}
 if(form.id==='recover-form'){await api('/api/auth/recover',{method:'POST',body:JSON.stringify(input)});$('#modal').close();toast('Если учётная запись существует, письмо придёт на рабочую почту.');return;}
 if(form.id==='password-form'){if(input.password!==input.confirm)throw new Error('Пароли не совпадают.');await api('/api/auth/password',{method:'POST',body:JSON.stringify({password:input.password})});$('#modal').close();await load();render();toast('Пароль установлен');return;}
 if(form.dataset.entityForm){const table=form.dataset.entityForm;const id=form.dataset.id||null;const values={...input};const doctor_ids=new FormData(form).getAll('doctor_ids');delete values.doctor_ids;
  for(const key of ['direction_id','branch_id','assignee_id','owner_id','goal_id','content_id','category_id','campaign_id'])if(key in values&&!values[key])values[key]=null;
  for(const key of ['due_date','next_date','ends_on'])if(key in values&&!values[key])values[key]=null;
  if('publish_at'in values)values.publish_at=values.publish_at?new Date(values.publish_at+':00+05:00').toISOString():null;
  if('external_id'in values&&!values.external_id)values.external_id=null;if('amount'in values)values.amount=Number(values.amount);
  if('monthly_target'in values)values.monthly_target=Number(values.monthly_target);
  if('archived'in values)values.archived=values.archived==='true';
  if(table==='content_plans'&&values.ends_on<values.starts_on)throw new Error('Конец периода должен быть не раньше начала.');
  if(table==='content_items'&&!cfg.demo){await api('/api/content',{method:'POST',body:JSON.stringify({id,values,doctor_ids})});await load();}
  else{const result=await save(table,values,id);if(table==='content_items'){data.content_doctors=data.content_doctors.filter(x=>x.content_id!==result.id);doctor_ids.forEach(doctor_id=>data.content_doctors.push({content_id:result.id,doctor_id}));persist();}}
 }else if(form.id==='weekly-form'){
  const payload={...input};const receipt=Number(payload.receipt);delete payload.receipt;
  if(new Date(payload.week_start+'T12:00:00Z').getUTCDay()!==1)throw new Error('Выберите понедельник отчётной недели.');
  for(const k of ['inquiries','bookings','first_visits','registrations','orders','participants'])payload[k]=payload[k]===''?null:Number(payload[k]);payload.campaign_id=payload.campaign_id||null;
  if(cfg.demo){if(!manager())throw new Error('Недостаточно прав.');let r=data.weekly_reports.find(r=>['week_start','branch_id','direction_id','source_id','campaign_id'].every(k=>(r[k]||null)===(payload[k]||null)));if(r)Object.assign(r,payload);else{r={...payload,id:uuid()};data.weekly_reports.push(r);}data.weekly_receipts=data.weekly_receipts.filter(x=>x.report_id!==r.id);data.weekly_receipts.push({report_id:r.id,amount:receipt,currency:'TJS'});persist();}else{await api('/api/weekly',{method:'POST',body:JSON.stringify({payload,receipt})});await load();}
 }else if(form.id==='decision-form'){await decision(form.dataset.record,form.dataset.value,form.dataset.medical==='true',input.comment);
 }else if(form.id==='comment-form'){await save('comments',{body:input.body,content_id:form.dataset.contentId});contentDetail(form.dataset.contentId);return;
 }else if(form.id==='partner-activity-form'){await save('partner_activities',{body:input.body,partner_id:form.dataset.partnerId});
 }else if(form.id==='publication-form'){
  const c=data.content_items.find(c=>c.id===form.dataset.contentId);
  if(form.dataset.manual==='true'){
   const u=new URL(input.permalink);if(u.protocol!=='https:'||!['www.instagram.com','instagram.com','www.facebook.com','facebook.com'].includes(u.hostname))throw new Error('Нужна ссылка на публикацию Instagram или Facebook.');
   if(cfg.demo){await save('content_items',{status:'published'},c.id);await save('comments',{content_id:c.id,body:'Опубликовано вручную: '+u.href});}else{await api('/api/manual-publication',{method:'POST',body:JSON.stringify({content_id:c.id,permalink:u.href})});await load();}
  }else{
   if(cfg.demo)throw new Error('Демо не отправляет публикации. Подключите Supabase и Meta для проверки отправки.');
   await api('/api/publish',{method:'POST',body:JSON.stringify({content_id:c.id,account_id:input.account_id,scheduled_at:new Date(input.scheduled_at+':00+05:00').toISOString()})});await load();
  }
 }
 $('#modal').close();render();toast('Сохранено');
 }catch(err){if(error)error.textContent=err.message;else toast(err.message);}finally{saving=false;if(submit)submit.disabled=false;}
});
function exportCsv(){
 const f=financial();let rows;
 if(current==='finance'&&manager())rows=[['Назначение','Направление','Дата','Тип','Сумма, сомони'],...f.expenses.map(e=>[e.title,dir(e.direction_id)?.name||'Общее',e.paid_on,e.type,e.amount])];
 else rows=[['Неделя','Филиал','Направление','Источник','Обращения','Записи','Первичные посещения'],...f.reports.map(r=>[r.week_start,data.branches.find(b=>b.id===r.branch_id)?.name,dir(r.direction_id)?.name,data.categories.find(c=>c.id===r.source_id)?.name,r.inquiries,r.bookings,r.first_visits])];
 const cell=v=>{let text=String(v??'');if(/^[=+\-@\t\r]/.test(text))text="'"+text;return '"'+text.replace(/"/g,'""')+'"';};
 const blob=new Blob(['\ufeff'+rows.map(row=>row.map(cell).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`family-dent-${current}-${localDate()}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
}
function baseLogin(message=''){document.title='Вход · Family Dent';$('#app').innerHTML=`<div class="login-shell"><section class="login-story"><div class="brand"><img src="/assets/family-dent.png" alt="Family Dent"><small>Marketing space</small></div><div><div class="eyebrow">ПРОСТРАНСТВО КОМАНДЫ</div><h1>Одна команда.<br>Больше возможностей.</h1><p>Планируйте продвижение, создавайте контент и следите за результатами шести направлений.</p></div><small>Family Dent · Душанбе</small></section><section class="login-form"><div class="login-inner"><div class="eyebrow">С ВОЗВРАЩЕНИЕМ</div><h2>Войти в пространство</h2><p>Используйте учётную запись, которую вам выдал IT-руководитель.</p>${cfg.configured?`<form id="login-form">${field('email','Рабочая почта','email','','required autocomplete="username"')}${field('password','Пароль','password','','required autocomplete="current-password"')}<div class="form-error" role="alert">${esc(message)}</div><button type="submit" class="button">Войти ${icon('arrow')}</button></form>`:`<div class="info-strip">Подключение Supabase ещё не настроено. IT-руководителю нужно заполнить переменные сервера и выполнить миграцию базы.</div>`}<div class="login-footnote">Финансовые данные доступны только уполномоченным сотрудникам. Личные сведения пациентов здесь не хранятся.</div></div></section></div>`;}
function login(message=''){baseLogin(message);if(cfg.configured)$('.login-inner').insertAdjacentHTML('beforeend','<button class="text-link spaced" data-action="recover">Восстановить доступ</button>');}
window.addEventListener('popstate',()=>{current=location.pathname.split('/')[1]||'dashboard';render();});
try{
 cfg=await api('/api/config');current=location.pathname.split('/')[1]||'dashboard';
 const invitation=new URLSearchParams(location.hash.slice(1));const passwordSetup=['invite','recovery'].includes(invitation.get('type'));
 if(passwordSetup&&invitation.get('access_token')){
  const tokens={access_token:invitation.get('access_token'),refresh_token:invitation.get('refresh_token')};
  history.replaceState({},'',location.pathname);await api('/api/auth/invitation',{method:'POST',body:JSON.stringify(tokens)});
 }
 await load();render();
 if(passwordSetup)modal('Установить пароль',`<form id="password-form"><p class="notes">Придумайте пароль длиной не менее 12 символов.</p>${field('password','Новый пароль','password','','required minlength="12" autocomplete="new-password"')}${field('confirm','Повторите пароль','password','','required minlength="12" autocomplete="new-password"')}${formEnd('Сохранить пароль')}</form>`);
 if(new URLSearchParams(location.search).has('connected'))toast('Подключение Meta завершено. Проверьте статусы аккаунтов.');
}catch(err){if(err.status!==401)console.error(err.stack);login(err.status===401?'':err.message);}
